// Symptom: nothing spreads apart
ScrollView(.horizontal) {
  HStack {
    Card(first)
    Spacer()      // proposed nil width -> answers minLength. There is no slack to absorb.
    Card(second)
  }
}

// The proposal the HStack actually receives:
//   ProposedViewSize(width: nil, height: 320)
//   nil       = "what is your ideal width?"
//   .infinity = "take as much as you want"
//   a number  = "here is what I can offer"

// Fix 1: the content commits to a width the container cannot dodge
ScrollView(.horizontal) {
  HStack(spacing: 12) {
    ForEach(cards) { Card($0).frame(width: 260) }
  }
  .padding(.horizontal, 16)
}

// Fix 2: size against the container instead of measuring it
ScrollView(.horizontal) {
  LazyHStack(spacing: 12) {
    ForEach(cards) { card in
      Card(card).containerRelativeFrame(.horizontal, count: 1, spacing: 12)
    }
  }
  .scrollTargetLayout()
}
.scrollTargetBehavior(.viewAligned)

// Same rule vertically: a Spacer cannot push until something commits to a height
ScrollView {
  VStack {
    Header()
    Spacer()                          // still collapses on its own
  }
  .containerRelativeFrame(.vertical)  // now the stack has a number to divide
}

// Symptom: the price truncates while the title still has room
HStack {
  Text(product.title)
  Spacer()
  Text(product.price)      // "$1,299.00" renders as "$1,2..."
}

// layoutPriority changes the OFFER: the stack serves priority 1 first, with all the width
HStack {
  Text(product.title)
  Spacer()
  Text(product.price).layoutPriority(1)
}

// fixedSize changes the ANSWER: propose nil to the child, report its ideal size upward
HStack {
  Text(product.title)      // gives way and wraps
  Spacer()
  Text(product.price).fixedSize()
}

// frame inserts a new parent and proposes ITS numbers down — it does not resize the child
Image("logo").frame(width: 40)                            // fixed-size image overflows
Image("logo").resizable().scaledToFit().frame(width: 40)  // resizable accepts the proposal

// ideal answers a nil proposal; min/max clamp what this wrapper reports to its own parent
Text(summary)
  .frame(idealWidth: 280, maxWidth: 360, alignment: .leading)
  .fixedSize(horizontal: false, vertical: true)   // stop vertical truncation, keep wrapping

// Wrong: fixedSize on both sides only moves the overflow off-screen
HStack {
  Text(product.title).fixedSize()
  Spacer()
  Text(product.price).fixedSize()
}

// Wrong: the reader eats the stack's leftover height and pins its content to the top-left
VStack {
  Title()
  GeometryReader { proxy in
    Chart(width: proxy.size.width)   // drawn at the top-left of a very tall box
  }
  Footer()                           // pushed to the bottom of the screen
}

// Read a value without taking space, and without a second layout pass
struct Card: View {
  @State private var width: CGFloat = 0

  var body: some View {
    Content()
      .onGeometryChange(for: CGFloat.self) { $0.size.width } action: { width = $0 }
      .overlay(alignment: .bottom) { Ruler(width: width) }
  }
}

// Geometry-driven effects with no @State at all
ScrollView(.horizontal) {
  HStack {
    ForEach(cards) { card in
      Card(card).visualEffect { content, proxy in
        content.scaleEffect(scale(for: proxy.frame(in: .scrollView).minX))
      }
    }
  }
}

// Size against the container rather than measuring it
Card().containerRelativeFrame(.horizontal, count: 2, spacing: 12)

// Still legitimate: in a background the reader inherits the host's size and costs nothing
Content()
  .background {
    GeometryReader { proxy in
      Color.clear.preference(key: SizeKey.self, value: proxy.size)
    }
  }

// Candidates in order; the last one is the fallback whether it fits or not
ViewThatFits(in: .horizontal) {
  HStack { ForEach(actions) { Label($0.title, systemImage: $0.icon) } }   // labels + icons
  HStack { ForEach(actions) { Image(systemName: $0.icon) } }              // icons only
  Menu("More") { ForEach(actions) { Button($0.title) {} } }               // fallback
}

// Trap: a greedy candidate has no ideal width, so it always "fits" and hides the rest
ViewThatFits {
  HStack {
    Text(title)
    Spacer()          // no ideal width -> this candidate always wins
  }
  Text(title).lineLimit(1)
}

// Right: every candidate is intrinsically sized, and the slack is added outside
ViewThatFits {
  HStack(spacing: 8) { Text(title); Text(subtitle) }
  VStack(alignment: .leading, spacing: 2) { Text(title); Text(subtitle) }
}
.frame(maxWidth: .infinity, alignment: .leading)

// State inside a candidate dies when a different candidate wins — own it one level up
struct PriceRow: View {
  @State private var isExpanded = false

  var body: some View {
    ViewThatFits(in: .horizontal) {
      WideBody(isExpanded: $isExpanded)
      NarrowBody(isExpanded: $isExpanded)
    }
  }
}

// The same row picks differently in the detail pane than it does full-screen —
// which no horizontalSizeClass check would have told you.
NavigationSplitView { Sidebar() } detail: { PriceRow() }

// The badge centres on the whole wrapped block, which is not what was drawn
HStack {
  Text(article.title)     // three lines
  Badge("NEW")
}

// Align on the first line's baseline instead
HStack(alignment: .firstTextBaseline) {
  Text(article.title)
  Badge("NEW")
    // Badge holds no text, so give it a baseline: its own vertical centre
    .alignmentGuide(.firstTextBaseline) { d in d[VerticalAlignment.center] }
}

// A custom alignment lines views up across different rows of a common stack
extension HorizontalAlignment {
  private enum ValueColumn: AlignmentID {
    static func defaultValue(in d: ViewDimensions) -> CGFloat { d[HorizontalAlignment.leading] }
  }
  static let valueColumn = HorizontalAlignment(ValueColumn.self)
}

VStack(alignment: .valueColumn, spacing: 8) {
  ForEach(spec) { row in
    HStack(spacing: 12) {
      Text(row.label).foregroundStyle(.secondary)
      Text(row.value).alignmentGuide(.valueColumn) { d in d[.leading] }
    }
  }
}

// What does NOT work: siblings of different stacks know nothing about each other
VStack {
  HStack { Text("Name"); Text(name) }
  HStack { Text("Email"); Text(email) }
}

// Either hoist the alignment as above, or use a Grid, which aligns by column
Grid(alignment: .leading, horizontalSpacing: 12) {
  GridRow { Text("Name"); Text(name) }
  GridRow { Text("Email"); Text(email) }
}

struct FlowLayout: Layout {
  var spacing: CGFloat = 8

  struct Cache { var width: CGFloat = .nan; var rows: [[Int]] = []; var size: CGSize = .zero }

  func makeCache(subviews: Subviews) -> Cache { Cache() }

  // Called many times per pass — key the cache on width
  private func flow(_ subviews: Subviews, width: CGFloat, cache: inout Cache) {
    guard cache.width != width else { return }
    var rows: [[Int]] = [[]]
    var x: CGFloat = 0, y: CGFloat = 0, rowHeight: CGFloat = 0, maxX: CGFloat = 0
    for i in subviews.indices {
      let size = subviews[i].sizeThatFits(.unspecified)  // the child's ideal size
      if x > 0, x + size.width > width {   // wrap onto a new row
        y += rowHeight + spacing
        x = 0; rowHeight = 0
        rows.append([])
      }
      rows[rows.count - 1].append(i)
      x += size.width + spacing
      maxX = max(maxX, x - spacing)
      rowHeight = max(rowHeight, size.height)
    }
    cache = Cache(width: width, rows: rows, size: CGSize(width: maxX, height: y + rowHeight))
  }

  func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout Cache) -> CGSize {
    flow(subviews, width: proposal.width ?? .infinity, cache: &cache)  // nil means "your ideal"
    return cache.size
  }

  func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize,
                     subviews: Subviews, cache: inout Cache) {
    flow(subviews, width: bounds.width, cache: &cache)
    var y = bounds.minY
    for row in cache.rows {
      var x = bounds.minX   // bounds may not start at the origin
      var rowHeight: CGFloat = 0
      for i in row {
        let size = subviews[i].sizeThatFits(.unspecified)
        subviews[i].place(at: CGPoint(x: x, y: y), anchor: .topLeading, proposal: .unspecified)
        x += size.width + spacing
        rowHeight = max(rowHeight, size.height)
      }
      y += rowHeight + spacing
    }
  }
}

// Used like any container view
FlowLayout(spacing: 6) { ForEach(tags, id: \.self) { Tag(text: $0) } }

// Wrong: the id tracks the data, so every edit destroys and rebuilds the row
List(items) { item in
  RowEditor(item: item)
    .id(item.updatedAt)     // new lifetime per keystroke: state gone, task restarted
}

// The item is already a dependency — the row re-renders with no id at all
List(items) { item in
  RowEditor(item: item)
}

// What an id change actually discards
struct Panel: View {
  @State private var draft = ""              // reallocated as ""
  @StateObject private var player = Player() // deallocated and rebuilt
  @FocusState private var focused: Bool      // drops, closing the keyboard

  var body: some View {
    TextField("Note", text: $draft)
      .focused($focused)
      .task { await player.prepare() }       // cancelled, then started again
  }
}

// Deliberate reset: a fresh form per record, not a fresh form per field
struct RecordScreen: View {
  let record: Record

  var body: some View {
    RecordForm(record: record)
      .id(record.id)        // switching records starts clean; editing one does not
  }
}

// An id used as a scroll anchor must be stable, or scrollTo aims at a view that is gone
ScrollViewReader { proxy in
  List(messages) { message in
    MessageRow(message: message).id(message.id)   // message.id, never message.editedAt
  }
  .onChange(of: latestID) { _, id in
    withAnimation { proxy.scrollTo(id, anchor: .bottom) }
  }
}

// Wrong: @State seeded from a prop. The initialiser runs once per lifetime, never again.
struct DetailEditor: View {
  let item: Item
  @State private var draft: String

  init(item: Item) {
    self.item = item
    _draft = State(initialValue: item.title)   // only the first item this slot ever saw
  }

  var body: some View { TextField("Title", text: $draft) }
}

// Selecting another item rebuilds the struct but reuses the slot, so draft stays stale
NavigationSplitView {
  List(items, selection: $selected) { Text($0.title) }
} detail: {
  if let selected { DetailEditor(item: selected) }
}

// Fix 1: bind to the model instead of copying it — one source of truth
@Observable final class Item { var title = "" }

struct BoundEditor: View {
  @Bindable var item: Item
  var body: some View { TextField("Title", text: $item.title) }
}

// Fix 2: if a scratch copy is genuinely needed, tie identity to the data
DetailEditor(item: selected).id(selected.id)   // a deliberate reset per record

// Fix 3: resync by hand — correct, but two sources of truth to keep in step
struct SyncedEditor: View {
  let item: Item
  @State private var draft = ""

  var body: some View {
    TextField("Title", text: $draft)
      .onAppear { draft = item.title }
      .onChange(of: item.id) { _, _ in draft = item.title }
  }
}

// The mirror image: changing the structure changes identity and throws the box away
VStack {
  if showBanner { Banner() }
  DetailEditor(item: item)   // its slot shifts, so its @State resets
}

struct Tag: Hashable { let name: String }

// Wrong: \.self over values that can repeat — two "swift" tags claim one identity
struct BadTagList: View {
  let tags: [Tag]
  var body: some View {
    ForEach(tags, id: \.self) { tag in
      TagChip(tag: tag)        // console: ID Tag(name: "swift") occurs multiple times
    }
  }
}

// Wrong: the offset is unique but not stable — deleting row 0 renumbers everything below
struct AlsoBad: View {
  let tags: [Tag]
  var body: some View {
    ForEach(Array(tags.enumerated()), id: \.offset) { _, tag in
      TagChip(tag: tag)        // state and animations follow the position, not the tag
    }
  }
}

// Right: a stable, namespaced id assigned where the data enters the app
struct Message: Identifiable {
  let id: String               // "inbox-4821" — two feeds cannot collide
  var body: String
}

extension Array where Element == Message {
  func deduplicated() -> [Message] {
    var seen = Set<String>()
    return filter { seen.insert($0.id).inserted }   // a retried page cannot double-append
  }
}

struct MessageList: View {
  let messages: [Message]
  var body: some View {
    List {
      ForEach(messages) { message in    // Identifiable: identity comes from the data
        MessageRow(message: message)
      }
    }
  }
}

// A constant range is fine; a range computed from data is not
ForEach(0..<3) { index in PageDot(index: index) }

// Wrong: onAppear means "built", not "on screen" — fires early and more than once
struct BadFeed: View {
  @State private var items: [Item] = []

  var body: some View {
    ScrollView {
      LazyVStack {
        ForEach(items) { item in
          Row(item: item)
            .onAppear {
              if item.id == items.last?.id { Task { await loadNextPage() } }
            }
        }
      }
    }
  }
}

// Right: the trigger is idempotent, so an early or repeated call is free
@Observable
final class Feed {
  private(set) var items: [Item] = []
  private var nextPage = 0
  private var loading = false

  func loadNextPage() async {
    guard !loading else { return }        // survives onAppear firing twice
    loading = true
    defer { loading = false }
    items += await api.page(nextPage)
    nextPage += 1
  }
}

struct GoodFeed: View {
  @State private var feed = Feed()

  var body: some View {
    ScrollView {
      LazyVStack(spacing: 12) {
        ForEach(feed.items) { item in
          Row(item: item).frame(height: 88)   // definite height: an honest content size
        }
        Color.clear.frame(height: 1)
          .onScrollVisibilityChange(threshold: 0.1) { visible in   // iOS 18: really visible
            if visible { Task { await feed.loadNextPage() } }
          }
      }
    }
  }
}

// Wrong: the row does not exist yet when the proxy is asked to find it
Button("Send") {
  messages.append(draft)
  proxy.scrollTo(draft.id, anchor: .bottom)   // resolved against the old tree
}

// Also wrong: a delay that happens to work on a fast phone
DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) { proxy.scrollTo(draft.id) }

// Right: the position is state, so SwiftUI applies it once the content exists
struct Chat: View {
  @State private var messages: [Message] = []
  @State private var position = ScrollPosition(idType: Message.ID.self)   // iOS 18

  var body: some View {
    ScrollView {
      LazyVStack(spacing: 8) {
        ForEach(messages) { MessageBubble(message: $0) }
      }
      .scrollTargetLayout()          // the container tracks its children's identities
    }
    .scrollPosition($position)
    .defaultScrollAnchor(.bottom)    // opens at the newest message
    .onChange(of: messages.count) {
      withAnimation { position.scrollTo(edge: .bottom) }
    }
  }
}

// A carousel measured against the container, not against the screen
ScrollView(.horizontal) {
  LazyHStack(spacing: 12) {
    ForEach(cards) { card in
      CardView(card: card)
        .containerRelativeFrame(.horizontal, count: 3, spacing: 12)
    }
  }
  .scrollTargetLayout()
}
.scrollTargetBehavior(.viewAligned)
.contentMargins(.horizontal, 16, for: .scrollContent)

// Wrong: 2,000 views, each with layout, identity and hit testing, rebuilt every tick
struct BadWaveform: View {
  let samples: [Float]

  var body: some View {
    HStack(alignment: .center, spacing: 1) {
      ForEach(samples.indices, id: \.self) { i in
        Rectangle().frame(width: 2, height: CGFloat(samples[i]) * 80)
      }
    }
  }
}

// Right: one view, one draw per frame, paced by the display link
struct Waveform: View {
  let samples: [Float]

  var body: some View {
    TimelineView(.animation) { timeline in          // redraws on the display link
      Canvas { context, size in
        let step = size.width / CGFloat(max(samples.count, 1))
        let phase = timeline.date.timeIntervalSinceReferenceDate
        var bars = Path()
        for (i, sample) in samples.enumerated() {
          let height = CGFloat(sample) * size.height * (0.9 + 0.1 * sin(phase * 4))
          bars.addRect(CGRect(x: CGFloat(i) * step,
                              y: (size.height - height) / 2,
                              width: max(step - 1, 0.5),
                              height: height))
        }
        context.fill(bars, with: .color(.accentColor))   // one path, one fill
      }
    }
    .frame(height: 80)
    .contentShape(.rect)                    // hit testing is yours to define now
    .accessibilityLabel("Audio waveform")   // the canvas has no children to describe
  }
}

// Wrong: one modifier, three shadows — the effect reaches each leaf, not the group
VStack(alignment: .leading, spacing: 8) {
  Text("Weekly report").font(.headline)
  Image("chart").resizable().scaledToFit()
  Text("Updated 5 minutes ago").font(.caption)
}
.shadow(radius: 8)

// Right: flatten first, then shadow the composed result once
VStack(alignment: .leading, spacing: 8) {
  Text("Weekly report").font(.headline)
  Image("chart").resizable().scaledToFit()
  Text("Updated 5 minutes ago").font(.caption)
}
.compositingGroup()
.shadow(radius: 8)

// The classic opacity case: two overlapping circles at 50%
ZStack {
  Circle().fill(.blue).frame(width: 80)
  Circle().fill(.pink).frame(width: 80).offset(x: 40)
}
.opacity(0.5)            // each circle is 50%, so the overlap reads as solid

ZStack {
  Circle().fill(.blue).frame(width: 80)
  Circle().fill(.pink).frame(width: 80).offset(x: 40)
}
.compositingGroup()
.opacity(0.5)            // the pair is composed, then faded as one

// Cheapest of all when the card already has a silhouette to shadow
CardContent()
  .padding()
  .background(.thinMaterial, in: .rect(cornerRadius: 12))
  .shadow(color: .black.opacity(0.15), radius: 8, y: 2)

// Wrong: the whole screen ignores the safe area, so the header and the fields go with it
struct BadScreen: View {
  @State private var name = ""

  var body: some View {
    VStack {
      Text("Profile").font(.largeTitle)          // now sits under the status bar
      Form { TextField("Name", text: $name) }    // no longer lifts for the keyboard
    }
    .background(LinearGradient(colors: [.indigo, .black],
                               startPoint: .top, endPoint: .bottom))
    .ignoresSafeArea()
  }
}

// Right: only the background bleeds; the content keeps its insets
struct GoodScreen: View {
  @State private var name = ""
  @FocusState private var focused: Bool

  var body: some View {
    VStack {
      Text("Profile").font(.largeTitle)
      Form { TextField("Name", text: $name).focused($focused) }
    }
    .background {
      LinearGradient(colors: [.indigo, .black], startPoint: .top, endPoint: .bottom)
        .ignoresSafeArea()          // the ignoring subtree is one gradient
    }
    .safeAreaInset(edge: .bottom) {
      SaveBar()                     // joins the safe area and rides the keyboard
    }
    .toolbar {
      ToolbarItemGroup(placement: .keyboard) {
        Spacer()
        Button("Done") { focused = false }
      }
    }
  }
}

// A hero image bleeds under the status bar only, and only for that one layer
Image("cover").resizable().scaledToFill()
  .ignoresSafeArea(.container, edges: .top)

// Wrong: `content` is one view, so the divider is drawn once for the whole ForEach
struct BadCard<Content: View>: View {
  @ViewBuilder var content: Content

  var body: some View {
    VStack(alignment: .leading) {
      content
      Divider()
    }
  }
}

// Right: resolve the children, then decorate each one
struct Card<Content: View>: View {
  @ViewBuilder var content: Content

  var body: some View {
    Group(subviews: content) { subviews in
      if subviews.isEmpty {
        EmptyView()                     // an empty card draws no chrome either
      } else {
        VStack(alignment: .leading, spacing: 0) {
          ForEach(subviews) { subview in
            subview
              .bold(subview.containerValues.isPinned)
              .padding(.vertical, 10)
            if subview.id != subviews.last?.id { Divider() }
          }
        }
        .padding(.horizontal, 12)
        .background(.thinMaterial, in: .rect(cornerRadius: 12))
      }
    }
  }
}

// A child tags itself; the container reads the tag
extension ContainerValues {
  @Entry var isPinned: Bool = false
}

Card {
  Text("Inbox")
  Text("Starred").containerValue(\.isPinned, true)
  ForEach(folders) { Text($0.name) }   // expands into individual subviews
}

// Per-child decoration with no need for the collection itself
ForEach(subviewOf: content) { subview in
  subview.padding(.vertical, 6)
}

// Wrong: the child measures itself, the parent stores it, and the resize re-measures
struct HeightKey: PreferenceKey {
  static let defaultValue: CGFloat = 0
  static func reduce(value: inout CGFloat, nextValue: () -> CGFloat) { value = nextValue() }
}

struct BadRow: View {
  let post: Post
  @State private var height: CGFloat = 0     // written from layout, on every frame

  var body: some View {
    let _ = Self._printChanges()             // silent here: the cost is below body
    HStack { Avatar(); Text(post.body) }
      .background(GeometryReader { proxy in
        Color.clear.preference(key: HeightKey.self, value: proxy.size.height)
      })
      .onPreferenceChange(HeightKey.self) { height = $0 }
      .frame(height: height)                 // the frame feeds the measurement it came from
  }
}

// Right: a definite size, no feedback loop, bounded text
struct GoodRow: View {
  let post: Post

  var body: some View {
    HStack(spacing: 12) {
      Avatar().frame(width: 44, height: 44)
      Text(post.body).lineLimit(2)           // bounded: one line-breaking pass
    }
    .frame(height: 72)                       // the container stops asking
  }
}

// A custom Layout answers several proposals per pass — cache the arrangement
struct Flow: Layout {
  struct Cache { var rows: [[Int]] = []; var proposal: ProposedViewSize = .unspecified }

  func makeCache(subviews: Subviews) -> Cache { Cache() }

  func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout Cache) -> CGSize {
    if cache.proposal != proposal {
      cache.rows = arrange(subviews, in: proposal)   // computed once per proposal
      cache.proposal = proposal
    }
    return size(of: cache.rows)
  }
}
